TLM.f("Tempora/Pent17-4",{"officium":"Feria Quinta infra Hebdomadam XVII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent17-0","from":{"Introitus":"Tempora/Pent17-0","Oratio":"Tempora/Pent17-0","Lectio":"Tempora/Pent17-0","Graduale":"Tempora/Pent17-0","Evangelium":"Tempora/Pent17-0","Offertorium":"Tempora/Pent17-0","Secreta":"Tempora/Pent17-0","Communio":"Tempora/Pent17-0","Postcommunio":"Tempora/Pent17-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:137; 118:124"},{"k":"text","la":"Justus es, Dómine, et rectum judícium tuum: fac cum servo tuo secúndum misericórdiam tuam."},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justus es, Dómine, et rectum judicium tuum: fac cum servo tuo secúndum misericórdiam tuam."}],"Oratio":[{"k":"text","la":"Da, quǽsumus, Dómine, pópulo tuo diabólica vitáre contágia: et te solum Deum pura mente sectári."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","la":"Ephes 4:1-6"},{"k":"text","la":"Fratres: Obsecro vos ego vinctus in Dómino, ut digne ambulétis vocatióne, qua vocáti estis, cum omni humilitáte et mansuetúdine, cum patiéntia, supportántes ínvicem in caritáte, sollíciti serváre unitátem spíritus in vínculo pacis. Unum corpus et unus spíritus, sicut vocáti estis in una spe vocatiónis vestræ. Unus Dóminus, una fides, unum baptísma. Unus Deus et Pater ómnium, qui est super omnes et per ómnia et in ómnibus nobis. Qui est benedíctus in sǽcula sæculórum. Amen."}],"Graduale":[{"k":"ref","la":"Ps 32:12; 32:6"},{"k":"text","la":"Beáta gens, cujus est Dóminus Deus eórum: pópulus, quem elégit Dóminus in hereditátem sibi."},{"k":"text","la":"Verbo Dómini cœli firmáti sunt: et spíritu oris ejus omnis virtus eórum. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 101:2"},{"k":"text","la":"Dómine, exáudi oratiónem meam, et clamor meus ad te pervéniat. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 22:34-46"},{"k":"text","la":"In illo témpore: Accessérunt ad Jesum pharisǽi: et interrogávit eum unus ex eis legis doctor, tentans eum: Magíster, quod est mandátum magnum in lege? Ait illi Jesus: Díliges Dóminum, Deum tuum, ex toto corde tuo et in tota ánima tua et in tota mente tua. Hoc est máximum et primum mandátum. Secúndum autem símile est huic: Díliges próximum tuum sicut teípsum. In his duóbus mandátis univérsa lex pendet et prophétæ. Congregátis autem pharisǽis, interrogávit eos Jesus, dicens: Quid vobis vidétur de Christo? cujus fílius est? Dicunt ei: David. Ait illis: Quómodo ergo David in spíritu vocat eum Dóminum, dicens: Dixit Dóminus Dómino meo, sede a dextris meis, donec ponam inimícos tuos scabéllum pedum tuórum? Si ergo David vocat eum Dóminum, quómodo fílius ejus est? Et nemo poterat ei respóndere verbum: neque ausus fuit quisquam ex illa die eum ámplius interrogáre."}],"Offertorium":[{"k":"ref","la":"Dan 9:17; 9:18; 9:19"},{"k":"text","la":"Orávi Deum meum ego Dániel, dicens: Exáudi, Dómine, preces servi tui: illúmina fáciem tuam super sanctuárium tuum: et propítius inténde pópulum istum, super quem invocátum est nomen tuum, Deus."}],"Secreta":[{"k":"text","la":"Majestátem tuam, Dómine, supplíciter deprecámur: ut hæc sancta, quæ gérimus, et a prætéritis nos delictis éxuant et futúris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 75:12-13"},{"k":"text","la":"Vovéte et réddite Dómino, Deo vestro, omnes, qui in circúitu ejus affértis múnera: terríbili, et ei qui aufert spíritum príncipum: terríbili apud omnes reges terræ."}],"Postcommunio":[{"k":"text","la":"Sanctificatiónibus tuis, omnípotens Deus, et vítia nostra curéntur, et remédia nobis ætérna provéniant."},{"k":"macro","name":"Per Dominum"}]},"hr":{"02fa9e85e6c5278d":{"t":"Ps 118, 137 i 124, Ps 118, 1\n(Ps 118, 137 i 124) Pravedan si. Gospodine, i pravedne su tvoje odluke! Učini svojemu slugi po milosrđu svojemu. (Ps 118, 1) Blago onima koji idu neokaljanim putem, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 137 i 124) Pravedan si. Gospodine, i pravedne su tvoje odluke! Učini svojemu slugi po milosrđu svojemu.","kn":"(Ps. 118, 137). Pravedan si. Gospodine, i prav je sud Tvoj; učini sa slugom svojim po 'milosti svojoj. (Ps. 118, 1) Blaigo onima, koji su čista života, koji žive po zakonu Gospodnjetn, . Slava Ocu ... Pravedan s.: . . .","knRef":"Kniewald 1942, str. 406–407 (snimka 204) (OCR)"},"446cbcdfa6cfb3fe":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine, puku svojemu da izbjegne pogubnom utjecaju đavla i da čiste duše teži k tebi, jedinomu Bogu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8cf55b4907713e63":{"t":"Ef 4, 1-6\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo, ja Gospodnji sužanj molim vas da živite dostojno zvanja u kojemu ste pozvani, sa svom poniznosti, krotkosti i strpljivosti, podnoseći jedan drugoga u ljubavi. Jedno tijelo i jedan Duh, kao što ste pozivom pozvani k jednoj nadi. Jedan Gospodin, jedna vjera, jedan krst, jedan Bog i Otac sviju, koji je nad svima i za sve i u svima nama, koji je blagoslovljen u vijeke vjekova. Amen.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (4, 1-6). Braćo! Molim vas ja, sužanj radi Gospo- dina, da živite dostojno prema zvanju, u koje ste pozvani, sa svom poniznošću i krotkošću, sa strpljivošću podnoseći jedan drugoga u ljubavi, nastojte povezani mirom čuvati jedinstvo duha: Jedno tijelo i jedan duh, kao što ste radi svoga zvanja pozvani u jednoj nadi. Jedan Gospodlo, jedna vjera, jedan krst, jedan Bog i Otac svih, koji je nad svima i za sve i u svima nama, koji je blagoslovljen u vljeke vjekova, Amen.","knRef":"Kniewald 1942, str. 406–407 (snimka 204) (OCR)"},"103f94951def21c1":{"t":"Ps 32, 12 i 6\nBlago narodu kojemu je Bog Gospodin, puku koji on izabra sebi za baštinu! Riječju su Gospodnjom stvorena nebesa, i dahom njegovih usta sva vojska njihova.\n\nPs 101, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodine, usliši molitvu moju i vapaj moj k tebi da dođe. <i>Aleluja</i>.","kn":"(Ps. 32, 12, 6). Blago narodu, kojemu je Gospodin Bog njihov; plemenu, koje izabra Gospodin za baštinu sebi. Riječju Gosipodnjom utvrđena su nebesa i duhom usta njegovih sva sila njihova.\n\nAleluja, aleluja. (Ps. 101, 2) Gospodine, usliši molitvu moju i vapaj moj k Tebi da dođe, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 406–407 (snimka 204) (OCR)"},"d923d77c5c581a01":{"t":"Mt 22, 34–46\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme pristupe k Isusu farizeji i između njih neki pismoznanac koji kušajući Isusa upita: Učitelju, koja je najveća zapovijed u zakonu? Isus mu odgovori: Ljubi Gospodina Boga svoga svim srcem svojim, svom dušom svojom i svom pameti svojom! Ovo je najveća i prva zapovijed. Druga je ovoj slična: Ljubi bližnjega svoga kao samoga sebe! U ovim je dvjema zapovijedima sav zakon i proroci. A kada se skupe farizeji, upita ih Isus: Što vi mislite o Kristu? Čiji je on Sin? Odgovore mu: Davidov. Reče im: Kako ga onda David, potaknut od Duha, naziva Gospodinom, kad kaže: Reče Gospodin Gospodinu mojemu: Sjedi mi s desne strane, dok ne položim tvoje neprijatelje pod tvoje noge? Pa ako ga David naziva Gospodinom, kako mu može biti sin? I nitko mu nije mogao odgovoriti ni riječi, niti ga se tko od toga dana usudi više pitati.","kn":"t Slijedi sveto evanđelje po Mateju (22, 34-46). U ono vrijeme pristuplše k Isusu farizeji i među njima jedan zakonodavac kušajući ga upita: Učitelju, koja je najveća zapovijed u zakonu? Isus mu odgovori: Ljubi Gospodina Boga svoga svim srcem svojim i svom dušom svojom i svim umom svojim. Ovo je najveća i prva zapovijed. A druga je ovoj jednaka: Ljubi svoga bližnjega kao samoga sebe. O ovim dvjema zapovijedima ovisi sav zakon i proroci. A kad se sabraše farizeji, upita ih Isus: Što vi mislite o Kristu, čiji je on sin? Odgovore mu: Davidov. Reče im: Pa kako ga David u duhu naziva Gospodinom. kad kaže: Reče Gospodin Gospodinu moje- Sv. Franciska Rimska 9. III. mu: Sjedi meni s desne, dok ne postavim tvoje neprijatelje za podnožje tvojim nogama?^ Ako, dakle, David njega naziva Gospodinom, kako mu je sin? I nitko mu nije mogao odgovoriti ni riječi, niti se više itko usudio pitati ga od toga dana,","knRef":"Kniewald 1942, str. 520–521 (snimka 261) (OCR)"},"a950bb1958f141ae":{"t":"Dn 9, 17, 18 i 19\nMolio sam se Bogu svome ja Danijel govoreći: Usliši, Gospodine, molitve sluge svoga. Obasjaj licem svojim svetište svoje, milostivo pogledaj ovaj narod nad kojim je zazvano sveto ime tvoje, Bože.","kn":"(Dan. 9, 17-19). Molih se Bogu svojemu ja, Daniel, govoreći: Usliši, Gospodine molitve sluge svoga, obasjaj licem svojim svetište svoje i milostiv poglećiaj na puk ovaj, koji priziva ime Tvoje, Bože!","knRef":"Kniewald 1942, str. 408–409 (snimka 205) (OCR)"},"4679dfbc08022f21":{"t":"Veličanstvo tvoje, Gospodine, smjerno molimo da nas od prošlih i budućih prestupaka oslobodi ovo sveto djelo što ga izvršujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Smjerno molimo. Gospodine, veličanstvo Tvoje, da nas ove svetinje, što ih vršimo, oslobode i od prošlih i od budućih prestupaka, po G. n.","knRef":"Kniewald 1942, str. 408–409 (snimka 205) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"8578722efd43781a":{"t":"Ps 75, 12-13\nZavjetujte se i izvršite zavjete Gospodinu Bogu svojemu. Svi oko njega neka prinesu darove strašnome, njemu koji kroti duh knezova, koji je strašan kraljevima zemlje.","kn":"(Fs. 75, 12,. 13). Zavjetujte i žrtvujte svi, koji ste unaokolo. Gospodinu Bogu svomu, svesilnomu, koji ukroćava duh knezovima, koji je strašan svim kraljevima zemaljskim. r","knRef":"Kniewald 1942, str. 408–409 (snimka 205) (OCR)"},"2104d956a558a7f0":{"t":"<i>Pomolimo se</i>.\nSvemoćni Bože, neka nas tvoja posvetna otajstva iscijele od opačina i neka nam budu na vječnu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući Bože, neka se Tvojim posvetilištima i naše opačine iscijele i vječne nam pomoći prolzlđu, po G. n.","knRef":"Kniewald 1942, str. 408–409 (snimka 205) (OCR)"}}});
